/**
 * @name Potential Object Injection
 * @description Writing to sensitive attributes like __dict__ or __class__ using user-controlled data can lead to object injection.
 * @kind path-problem
 * @problem.severity error
 * @id py/object-injection
 * @tags security
 *       external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking

module ObjectInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Broad source: any function parameter
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: value assigned to a sensitive attribute
    exists(Attribute attr, Assign assign |
      assign.getTargets().getAnItem() = attr and
      attr.getName() in ["__dict__", "__class__", "__code__", "__defaults__", "__kwdefaults__"] and
      sink.asExpr() = assign.getValue()
    )
    or
    // Sink: setattr(obj, "sensitive_attr", value)
    exists(Call call, Name name |
      call.getFunc() = name and
      name.getId() = "setattr" and
      call.getArg(1).(StrConst).getText() in ["__dict__", "__class__", "__code__", "__defaults__", "__kwdefaults__"] and
      sink.asExpr() = call.getArg(2)
    )
  }
}

module ObjectInjectionFlow = TaintTracking::Global<ObjectInjectionConfig>;
import ObjectInjectionFlow::PathGraph

from ObjectInjectionFlow::PathNode source, ObjectInjectionFlow::PathNode sink
where ObjectInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential object injection: write to sensitive attribute from $@", source.getNode(), "parameter"
